import { CloudWatchClient, ListMetricsCommand, GetMetricDataCommand } from '@aws-sdk/client-cloudwatch';
const c = new CloudWatchClient({ region: process.env.AWS_REGION, endpoint: process.env.AWS_ENDPOINT_URL });
let metrics = [], next;
do {
  const r = await c.send(new ListMetricsCommand({ Namespace: 'Metering/Usage', NextToken: next }));
  metrics.push(...(r.Metrics||[]));
  next = r.NextToken;
} while (next);
console.log('COUNT', metrics.length);
for (const m of metrics) console.log(JSON.stringify(m.Dimensions));
// read samples for each
for (const m of metrics) {
  const r = await c.send(new GetMetricDataCommand({
    StartTime: new Date('2020-01-01'), EndTime: new Date('2030-01-01'),
    MetricDataQueries: [{ Id:'usage', MetricStat:{ Metric:{ Namespace:'Metering/Usage', MetricName: m.MetricName, Dimensions: m.Dimensions }, Period:60, Stat:'Maximum'}, ReturnData:true }],
  }));
  console.log('---', JSON.stringify(m.Dimensions.map(d=>d.Value)));
  console.log(JSON.stringify(r.MetricDataResults, null, 1));
}
EOF
